import { PlaneGeometry, Mesh, MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, vec2 } from 'three/tsl';

export default function createNode(config, ctx) {
  const assets = config.assets || {};
  const tex = ctx.textureLoader(assets.imageUrl);

  const atlas = config.atlas || {};
  const rect = atlas.sourceRect || { x: 0, y: 0, w: 512, h: 320 };

  // Plane sized to the atlas region aspect ratio
  const aspect = rect.w / rect.h;
  const planeW = 2.0;
  const planeH = planeW / aspect;
  const geometry = new PlaneGeometry(planeW, planeH);

  // Resolve atlas texture dimensions (fallback to region if unknown)
  const img = tex && tex.image;
  const texW = (img && (img.width || img.videoWidth)) || rect.w;
  const texH = (img && (img.height || img.videoHeight)) || rect.h;

  // Compute UV offset/repeat for the atlas region (respect flipY)
  const flipY = tex ? tex.flipY !== false : true;
  const offX = rect.x / texW;
  const repX = rect.w / texW;
  const repY = rect.h / texH;
  const offY = flipY ? 1 - (rect.y + rect.h) / texH : rect.y / texH;

  // TSL: sample the atlas sub-region
  const atlasUV = uv().mul(vec2(repX, repY)).add(vec2(offX, offY));
  const texNode = texture(tex, atlasUV);

  const material = new MeshBasicNodeMaterial();
  material.colorNode = texNode;
  material.transparent = true;
  material.depthWrite = false;
  material.toneMapped = false;

  const mesh = new Mesh(geometry, material);
  mesh.position.set(0, -0.35, -0.6);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);
  mesh.renderOrder = 1;

  // Billboard toward the camera (sprite render mode)
  mesh.onBeforeRender = (_renderer, _scene, camera) => {
    mesh.quaternion.copy(camera.quaternion);
  };

  mesh.userData.handlers = {};
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    // texture owned by shared loader cache; not disposed here
  };

  return mesh;
}
